cd /tmp/vally-eval-trial-CHxvsL && mkdir -p docs/features/pricing tests/CheckoutPricing.UnitTest/Features/Discount .copilot-tracking/skraft-plans/pricing/details/2026-08-12
cat > docs/features/pricing/discount.feature <<'EOF'
Feature: Loyalty tier discount at checkout

  A returning customer's loyalty tier reduces the basket subtotal.
  SETTLED: Bronze, Silver and Gold (AC-1 to AC-4).
  NOT DECIDED: Platinum. The business has agreed no reduction, so there is
  deliberately no scenario for it. Do not add one until an expected value exists.

  @discount @happy-path
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @discount @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @discount @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @discount @edge-case
  Scenario: Bronze customer with a tiny basket is charged a whole-cent amount
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/Discount/DiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_price()
    {
        // Bronze customer is charged the Bronze price
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
cd tests/CheckoutPricing.UnitTest && dotnet test --filter "FullyQualifiedName~DiscountAcceptanceTests" 2>&1 | tail -15

